 auto bind=[&](const StableId& fact,const StableId& kind,const StableId& player,Integer request,const FamilyLegacyState& before,const CollateralControlState& bindings){auto result=std::make_shared<CommitResult>();result->kind=kind;result->result_id=f.c.next_id("result").value;result->tick=f.c.tick();result->revision=++f.c.state().identity.revision;FamilyEffect effect;effect.success=true;effect.fact_id=fact;effect.heir_actor_id="second";effect.player_actor_id=player;result->details=std::make_shared<const ReceiptDetails>(ReceiptDetails{effect,{}});f.c.state().request_sequences.set("first",request);f.c.state().results.set("first:"+std::to_string(request),result);f.c.state().history.push_back({result->tick,result->kind,"first",result->result_id,{}});return bind_collateral_control_result_in_candidate(f.c,before,legacy,f.policies,bindings,f.state,"first",request,*result);};
